<?php declare(strict_types=1); namespace App\Infrastructure\Persistence\Doctrine\Review; use App\Domain\Review\Entity\UserConceptMastery;use App\Domain\Review\Enum\MasteryConfidence;use App\Domain\Review\Repository\UserConceptMasteryRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Review\Entity\ConceptMasteryRecord;use Doctrine\ORM\EntityManagerInterface; final class DoctrineUserConceptMasteryRepository implements UserConceptMasteryRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function find(string $u,string $s):?UserConceptMastery{$r=$this->em->find(ConceptMasteryRecord::class,['userId'=>$u,'taxonomySubjectId'=>$s]);return $r instanceof ConceptMasteryRecord?$this->map($r):null;} public function save(UserConceptMastery $m):void{$r=$this->em->find(ConceptMasteryRecord::class,['userId'=>$m->userId,'taxonomySubjectId'=>$m->taxonomySubjectId])??new ConceptMasteryRecord();$r->userId=$m->userId;$r->taxonomySubjectId=$m->taxonomySubjectId;$r->masteryScore=$m->masteryScore===null?null:(string)$m->masteryScore;$r->confidence=$m->confidence->value;$r->evidenceCount=$m->evidenceCount;$r->lastEvidenceAt=$m->lastEvidenceAt;$r->signals=$m->signals;$r->updatedAt=$m->updatedAt;$this->em->persist($r);} public function listForUser(string $u,int $o,int $l):array{$rs=$this->em->getRepository(ConceptMasteryRecord::class)->findBy(['userId'=>$u],['updatedAt'=>'DESC'],$l,$o);return array_map(fn($r)=>$this->map($r),$rs);} public function countForUser(string $u):int{return $this->em->getRepository(ConceptMasteryRecord::class)->count(['userId'=>$u]);} private function map(ConceptMasteryRecord $r):UserConceptMastery{return new UserConceptMastery($r->userId,$r->taxonomySubjectId,$r->masteryScore===null?null:(float)$r->masteryScore,MasteryConfidence::from($r->confidence),$r->evidenceCount,$r->lastEvidenceAt,$r->signals,$r->updatedAt);} }
